def reference(arr):
    """Obviously-correct model: True iff some right-shift yields sorted order."""
    if len(arr) == 0:
        return True
    s = sorted(arr)
    n = len(arr)
    if arr == s:
        return True
    for k in range(1, n):
        # right shift by k
        if arr[-k:] + arr[:-k] == s:
            return True
    return False

def right_rotate(arr, k):
    n = len(arr)
    if n == 0:
        return []
    k = k % n
    if k == 0:
        return list(arr)
    return list(arr[-k:] + arr[:-k])

